import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Performance Meeting 2022-03-17","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-03-17","date":"2022-03-17T00:00:00.000Z","updated":"2022-03-19T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-03-17.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-03-17.md","lastUpdated":1780460162000}'),o={name:"posts/2022/Ceph_Performance_Meeting_2022-03-17.md"};function r(s,l,n,h,c,u){return a(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 2022年3月17日早晨，会议稍有延迟开始。</li><li><strong>参与者</strong>: Adam和Gabby因休假缺席，其他核心团队成员参与。</li><li><strong>议题</strong>: 讨论Ceph存储系统的性能改进、Pull Requests (PRs)更新、日志优化以及已关闭的PRs。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>PRs更新</strong>:</p><ul><li><strong>Matt Benjamin的PR</strong>: 优化RGW性能，特别是日志处理，但未被合并。</li><li><strong>Josh Solomon的PR</strong>: 改进平衡器性能，已合并。</li><li><strong>线程局部指针的使用</strong>: 用于保存分片，已合并。</li><li><strong>性能标签的测试</strong>: 来自Chris的PR，虽关闭但相关工作仍在进行。</li><li><strong>池移除速度的改进</strong>: Igor的工作，通过引入集合列表预取，已关闭。</li></ul></li><li><p><strong>性能问题讨论</strong>:</p><ul><li><strong>SoftIron的更新</strong>: 讨论了Nautilus特定性能回归问题，尤其是ARM架构上的性能测试和优化。</li><li><strong>Crimson和ScienceStore的更新</strong>: 讨论了性能测试结果和潜在优化方向。</li></ul></li><li><p><strong>RocksDB性能问题</strong>:</p><ul><li><strong>生产环境中的问题</strong>: 讨论了一个生产集群中RocksDB性能问题，特别是与RGW的桶列表相关的问题。</li><li><strong>解决方案探讨</strong>: 讨论了可能的解决方案，包括RocksDB的TTL压缩和周期性压缩选项，以及是否需要升级RocksDB版本。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>进一步研究RocksDB的TTL压缩和周期性压缩选项，以解决桶列表性能问题。</li><li>考虑是否需要升级RocksDB版本，但需谨慎测试以避免潜在的兼容性问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续跟踪和研究RocksDB的压缩选项。</li><li>如果必要，进行RocksDB版本的升级测试。</li><li>下周会议将讨论Gabby和Adam关于PG的提案。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到了多个性能相关的讨论点，显示了团队对持续优化Ceph性能的承诺。</li><li>对于容器化部署的性能问题，团队表示需要进一步的研究和测试。</li></ul><h4 id="容器化性能问题" tabindex="-1">容器化性能问题 <a class="header-anchor" href="#容器化性能问题" aria-label="Permalink to &quot;容器化性能问题&quot;">​</a></h4><ul><li>讨论了在ARM架构上的性能下降，特别是在容器化部署中。</li><li>探讨了可能的解决方案，包括优化编译时选项和网络栈。</li></ul><h4 id="版本更新" tabindex="-1">版本更新 <a class="header-anchor" href="#版本更新" aria-label="Permalink to &quot;版本更新&quot;">​</a></h4><ul><li>考虑升级RocksDB版本，但需谨慎测试以避免兼容性问题。</li></ul><p>标签：</p><ul><li>[Ceph]</li><li>[分布式存储]</li><li>[性能优化]</li><li>[RocksDB]</li><li>[RGW]</li></ul>',17)])])}const p=e(o,[["render",r]]);export{g as __pageData,p as default};
